import {dateKey,dayDifference,adaptiveQuestions} from './learning.js';
export function weakestSkills(state,bank){const counts=new Map(),items=new Map(bank.map(q=>[q.id,q.skill]));for(const row of state.log){const skill=items.get(row.id);if(skill)counts.set(skill,(counts.get(skill)||0)+1);}return [...new Set(bank.map(q=>q.skill))].map(skill=>({skill,rating:state.skillRatings[skill]??1000,attempts:counts.get(skill)||0})).sort((a,b)=>a.rating-b.rating||b.attempts-a.attempts||a.skill.localeCompare(b.skill));}
export function buildStudyPlan(state,bank,today=dateKey()){if(!state.testDate)return{status:'needs-date',days:[],weakest:weakestSkills(state,bank)};const remaining=dayDifference(state.testDate,today);if(remaining<0)return{status:'past',days:[],remaining};if(remaining>730)return{status:'too-far',days:[],remaining};const ranked=weakestSkills(state,bank),eligible=bank.filter(q=>state.answers[q.id]?.failedAttempts>0),days=[];for(let i=0;i<=remaining;i++){const d=new Date(`${today}T12:00:00`);d.setDate(d.getDate()+i);const date=dateKey(d),done=state.planCompletions?.[date];if(done){days.push({...done,date,completed:true});continue;}const skill=ranked[Math.floor(i/2)%Math.min(6,ranked.length)].skill;let task;if(i===remaining)task={type:'testday',title:'Test day: a calm warm-up',minutes:5,skill:'Light recall',ids:[]};else if(i%4===1)task={type:'boss',title:'Boss Fight · 5 past misses',minutes:10,skill:'Review past mistakes',locked:eligible.length<5,ids:adaptiveQuestions(eligible,state,5,Date.parse(date)).map(q=>q.id)};else if(i%4===3)task={type:'mixed',title:'Mixed recall & pacing',minutes:15,skill:'Mixed skills',ids:adaptiveQuestions(bank,state,10,Date.parse(date)).map(q=>q.id)};else task={type:'focus',title:`Focus: ${skill}`,minutes:15,skill,ids:adaptiveQuestions(bank.filter(q=>q.skill===skill),state,8,Date.parse(date)).map(q=>q.id)};days.push({id:`${date}:${task.type}:${task.skill}`,date,...task,completed:false});}return{status:'ready',remaining,days,weakest:ranked,updatedAfterSession:state.sessions.length};}
